141: -- The conversation a request names, with the caller a member of its project; otherwise "not found", whether it does
142: -- not exist or the caller may not see it (the two answer alike). Locks its project's row first, then its own.
143: -- Membership is read again once the project's row is held (CON-01-CX-0006): a revocation that committed while this
144: -- call waited for the row is seen, so a member removed meanwhile neither writes nor withdraws. The first read only
145: -- keeps a caller who is no member from holding a project's row at all.
146: CREATE FUNCTION sophia.conversation_locked(p_conversation uuid) RETURNS sophia.conversations LANGUAGE plpgsql
147: SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
148: DECLARE c sophia.conversations; p uuid;
149: BEGIN
150:  SELECT project_id INTO p FROM sophia.conversations WHERE id=p_conversation;
151:  IF p IS NULL OR NOT sophia.is_member(p) THEN RAISE EXCEPTION 'Conversation not found' USING ERRCODE='22023'; END IF;
152:  PERFORM 1 FROM sophia.projects WHERE id=p FOR UPDATE;
153:  IF NOT sophia.is_member(p) THEN RAISE EXCEPTION 'Conversation not found' USING ERRCODE='22023'; END IF;
154:  SELECT * INTO c FROM sophia.conversations WHERE project_id=p AND id=p_conversation FOR UPDATE;
155:  RETURN c;
156: END $$;
157: REVOKE ALL ON FUNCTION sophia.conversation_locked(uuid) FROM PUBLIC;
