313: CREATE FUNCTION sophia.accept_room_invitation(p_token_sha256 bytea, p_email text) RETURNS jsonb LANGUAGE plpgsql
314: SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
315: DECLARE a uuid:=sophia.actor_id(); i sophia.room_invitations;
316: BEGIN
317:  IF a IS NULL THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
318:  SELECT * INTO i FROM sophia.room_invitations WHERE token_sha256=p_token_sha256;
319:  IF NOT FOUND OR i.kind<>'member' THEN RAISE EXCEPTION 'Invitation not found' USING ERRCODE='22023'; END IF;
320:  IF p_email IS NULL OR lower(p_email)<>i.email THEN
321:   RAISE EXCEPTION 'This invitation is for another email address' USING ERRCODE='42501'; END IF;
322:  PERFORM 1 FROM sophia.projects WHERE id=i.project_id FOR UPDATE;
323:  SELECT * INTO i FROM sophia.room_invitations WHERE id=i.id FOR UPDATE;
324:  IF EXISTS(SELECT 1 FROM sophia.project_members WHERE project_id=i.project_id AND actor_id=a AND active) THEN
325:   RETURN jsonb_build_object('projectId',i.project_id); END IF;
326:  IF i.revoked_at IS NOT NULL OR i.expires_at<=now() THEN RAISE EXCEPTION 'The invitation is closed' USING ERRCODE='40001'; END IF;
327:  IF i.uses>=i.max_uses THEN RAISE EXCEPTION 'The invitation has been used up' USING ERRCODE='40001'; END IF;
328:  INSERT INTO sophia.project_members AS pm(project_id,actor_id,role) VALUES(i.project_id,a,i.member_role)
329:   ON CONFLICT (project_id,actor_id) DO UPDATE SET active=true, role=EXCLUDED.role, revision=pm.revision+1;
330:  UPDATE sophia.projects SET audience_revision=audience_revision+1 WHERE id=i.project_id;
331:  UPDATE sophia.room_invitations SET uses=uses+1 WHERE id=i.id;
332:  PERFORM sophia.emit_project_event(i.project_id,'project.member_joined','project_member',a,1,'project.member');
333:  RETURN jsonb_build_object('projectId',i.project_id);
334: END $$;
