344: CREATE FUNCTION sophia.mission_forgettable(p_project uuid, p_entry uuid) RETURNS sophia.mission_entries LANGUAGE plpgsql
345: STABLE SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
346: DECLARE e sophia.mission_entries;
347: BEGIN
348:  SELECT * INTO e FROM sophia.mission_entries WHERE project_id=p_project AND id=p_entry;
349:  IF NOT FOUND THEN RAISE EXCEPTION 'Note not found' USING ERRCODE='22023'; END IF;
350:  IF NOT sophia.is_member(p_project) OR (e.actor_id<>sophia.actor_id() AND NOT sophia.is_admin(p_project)) THEN
351:   RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
352:  IF e.state='withdrawn' THEN RAISE EXCEPTION 'Stale note: it is already withdrawn' USING ERRCODE='40001'; END IF;
353:  RETURN e;
354: END $$;
355: REVOKE ALL ON FUNCTION sophia.mission_forgettable(uuid,uuid) FROM PUBLIC;

434: CREATE FUNCTION sophia.withdraw_mission_entry(p_project uuid, p_entry uuid, p_key text, p_expected jsonb, p_token text)
435: RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
436: DECLARE a uuid:=sophia.actor_id();
437:  semantic jsonb:=jsonb_build_object('entryId',p_entry,'expected',p_expected,'previewToken',p_token);
438:  prior jsonb; e sophia.mission_entries; shown record; expires bigint;
439:  v sophia.mission_entries; d sophia.decisions; receipt_value jsonb; r record; affected jsonb:='[]';
440: BEGIN
441:  IF a IS NULL OR NOT sophia.is_member(p_project) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
442:  IF p_expected IS NULL OR jsonb_typeof(p_expected->'entryIds') IS DISTINCT FROM 'array'
443:    OR jsonb_typeof(p_expected->'decisions') IS DISTINCT FROM 'array' THEN
444:   RAISE EXCEPTION 'Invalid withdrawal: it must name what the member was shown' USING ERRCODE='22023'; END IF;
445:  IF p_token IS NULL OR p_token !~ '^v1\.[0-9]{1,12}\.[0-9a-f]{64}$' THEN
446:   RAISE EXCEPTION 'Invalid withdrawal: it must carry the preview shown to the member' USING ERRCODE='22023'; END IF;
447:  PERFORM 1 FROM sophia.projects WHERE id=p_project FOR UPDATE;
448:  prior:=sophia.mission_prior(p_project,p_key,'withdraw_note',semantic);
449:  IF prior IS NOT NULL THEN RETURN prior; END IF;
450:  e:=sophia.mission_forgettable(p_project,p_entry);
451:  SELECT * INTO r FROM sophia.mission_forget_reach(p_project,p_entry,a,sophia.is_admin(p_project));

465:   RAISE EXCEPTION 'Stale withdrawal: the list shown has expired' USING ERRCODE='40001'; END IF;
466:  FOR v IN SELECT m.* FROM unnest(r.entry_ids) WITH ORDINALITY AS x(id,ord)
467:    JOIN sophia.mission_entries m ON m.project_id=p_project AND m.id=x.id ORDER BY x.ord LOOP
468:   UPDATE sophia.mission_entries SET state='withdrawn', changed_by=a, changed_at=now() WHERE project_id=p_project AND id=v.id;
469:   PERFORM sophia.mission_erase_source(p_project,v.source_id);
470:   affected:=affected||to_jsonb(v.id);
