473:    JOIN sophia.decisions m ON m.project_id=p_project AND m.id=x.id ORDER BY x.ord LOOP
474:   UPDATE sophia.decisions SET state='withdrawn', proposal=NULL, revision=revision+1 WHERE project_id=p_project AND id=d.id;
475:   PERFORM sophia.mission_erase_source(p_project,d.body_source_id);
476:   DELETE FROM sophia.mission_confirmation_targets WHERE project_id=p_project AND decision_id=d.id;
477:   IF d.kind='mission' THEN
478:    UPDATE sophia.project_revisions SET frame=jsonb_build_object('decisionId',d.id,'withdrawn',true)
479:     WHERE project_id=p_project AND frame->>'decisionId'=d.id::text;
