150: CREATE OR REPLACE FUNCTION sophia.decide_mission_change(p_project uuid, p_decision uuid, p_key text, p_request jsonb) RETURNS jsonb
151: LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
152: DECLARE a uuid:=sophia.actor_id(); choice text:=p_request->>'decision'; turn jsonb:=p_request->'turn'; semantic jsonb; prior jsonb;
153:  d sophia.decisions; affected jsonb:='[]'; receipt_value jsonb;
154: BEGIN
155:  IF a IS NULL OR NOT sophia.can_edit(p_project) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
156:  IF choice IS NULL OR choice NOT IN ('accept','reject') THEN RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
157:  IF jsonb_typeof(p_request->'expectedRevision')<>'number' THEN RAISE EXCEPTION 'Missing expected revision' USING ERRCODE='22023'; END IF;
158:  PERFORM 1 FROM sophia.projects WHERE id=p_project FOR UPDATE;
159:  IF NOT sophia.can_edit(p_project) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
160:  semantic:=jsonb_build_object('decisionId',p_decision,'decision',choice,'expectedRevision',p_request->'expectedRevision','turn',turn);
161:  prior:=sophia.mission_prior(p_project,p_key,'decide',semantic);
162:  IF prior IS NOT NULL THEN RETURN prior; END IF;
163:  SELECT * INTO d FROM sophia.decisions WHERE project_id=p_project AND id=p_decision FOR UPDATE;

133: CREATE OR REPLACE FUNCTION sophia.mission_erase_source(p_project uuid, p_source uuid) RETURNS void LANGUAGE plpgsql
134: SECURITY DEFINER SET search_path=pg_catalog,sophia AS $$
135: BEGIN
136:  DELETE FROM sophia.source_texts WHERE project_id=p_project AND source_id=p_source;
137:  UPDATE sophia.source_objects SET eligible=false, state='deleted', eligibility_revision=eligibility_revision+1, byte_length=0,
138:   sha256=encode(sha256(convert_to(gen_random_uuid()::text||gen_random_uuid()::text,'UTF8')),'hex')
139:   WHERE project_id=p_project AND id=p_source;
140:  UPDATE sophia.mission_requests SET semantic_request=(semantic_request-'text'-'proposal')||'{"redacted":true}',
141:   receipt=receipt||'{"sha256":null}'
142:   WHERE project_id=p_project AND receipt->>'sourceId'=p_source::text;
143:  PERFORM sophia.research_revoke_source(p_project,p_source);
144:  PERFORM sophia.design_revoke_source(p_project,p_source);
145: END $$;
